NS_IMETHODIMP nsMsgSearchSession::InterruptSearch() {
  AUTO_PROFILER_LABEL("nsMsgSearchSession::InterruptSearch", MAILNEWS);
  // NotifyListenersDone() may lead to the last reference to us being dropped.
  RefPtr<nsIMsgSearchSession> kungFuDeathGrip(this);
  nsCOMPtr<nsIMsgWindow> msgWindow(do_QueryReferent(m_msgWindowWeak));
  if (msgWindow) {
    EnableFolderNotifications(true);

    while (m_idxRunningScope < m_scopeList.Length()) {
      ReleaseFolderDBRef();
      m_idxRunningScope++;
    }
    // m_idxRunningScope = m_scopeList.Length() so it will make us not run

  }
  if (m_backgroundTimer) {
    m_backgroundTimer->Cancel();
    m_backgroundTimer = nullptr;
    NotifyListenersDone(NS_MSG_SEARCH_INTERRUPTED);
  }
  m_searchRunning = false;
  return NS_OK;
}

NS_IMETHODIMP nsMsgSearchSession::SkipSearch() {
  if (!m_searchPaused || m_idxRunningScope >= m_scopeList.Length()) {
    return NS_ERROR_FAILURE;
  }

  ReleaseFolderDBRef();
  ++m_idxRunningScope;
  return NS_OK;
}

